  --bg: #0b0f1a;
  --bg-elev: #131a2b;
  --bg-elev-2: #1a2238;
  --border: #2a3552;
  --border-strong: #3b4a72;
  --text: #eef1f8;
  --text-muted: #aab3cb;
  --accent: #7aa2ff;
  --accent-contrast: #0b0f1a;
  --danger: #ff7a85;
  --danger-bg: #3a1620;
  --danger-border: #7a2a36;
  --focus: #ffd166;
  --shadow: 0 20px 60px rgba(0, 0, 0, .6), 0 4px 12px rgba(0, 0, 0, .4);
  --radius: 12px;
}

* { box-sizing: border-box; }

html, body { height: 100%; }

body {
  margin: 0;
  background: radial-gradient(1200px 600px at 80% -10%, #1b2547 0%, transparent 60%),
              radial-gradient(900px 500px at -10% 110%, #1a2440 0%, transparent 60%),
              var(--bg);
  color: var(--text);
  font: 16px/1.55 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
  background: var(--bg-elev);
  color: var(--text);
  padding: .6rem 1rem;
  border: 1px solid var(--border-strong);
  border-radius: 0 0 8px 0;
  z-index: 100;
}
.skip-link:focus { left: 0; outline: 2px solid var(--focus); outline-offset: 2px; }

.site-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 1.5rem;
  border-bottom: 1px solid var(--border);
  background: rgba(10, 14, 26, .6);
  backdrop-filter: blur(8px);
}
.brand { font-weight: 700; letter-spacing: .04em; color: var(--text); }
.site-header nav ul {
  display: flex; gap: 1.25rem;
  list-style: none; margin: 0; padding: 0;
}
.site-header nav a {
  color: var(--text-muted);
  text-decoration: none;
  padding: .35rem .25rem;
  border-bottom: 2px solid transparent;
}
.site-header nav a:hover { color: var(--text); }
.site-header nav a[aria-current="page"] {
  color: var(--text);
  border-bottom-color: var(--accent);
}
.site-header nav a:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 3px;
  border-radius: 4px;
}

main {
  max-width: 880px;
  margin: 0 auto;
  padding: 2rem 1.25rem 4rem;
}
h1 { margin: 0 0 .25rem; font-size: clamp(1.5rem, 2.4vw, 2rem); }
.meta { margin: 0 0 1.25rem; color: var(--text-muted); font-size: .95rem; }

.preview {
  margin: 0 0 1.25rem;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow);
}
.preview-image {
  display: block;
  width: 100%;
  height: auto;
  max-width: 100%;
}
.preview figcaption {
  padding: .75rem 1rem;
  color: var(--text-muted);
  border-top: 1px solid var(--border);
  font-size: .92rem;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: .6rem;
  margin-bottom: 1rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  padding: .6rem 1rem;
  border-radius: 8px;
  border: 1px solid var(--border-strong);
  background: var(--bg-elev-2);
  color: var(--text);
  font: inherit;
  font-weight: 600;
  cursor: pointer;
  transition: background-color .15s, border-color .15s, transform .05s;
}
.btn:hover { background: #243056; }
.btn:active { transform: translateY(1px); }
.btn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.btn-secondary { /* default */ }

.btn-danger {
  background: var(--danger-bg);
  border-color: var(--danger-border);
  color: #ffd6db;
}
.btn-danger:hover { background: #4d1c28; border-color: #9a3645; }

.status:not(:empty) {
  margin-top: .75rem;
  padding: .6rem .9rem;
  border-radius: 8px;
  background: #14321f;
  border: 1px solid #2c6b44;
  color: #c8f3d6;
}

/* Dialog */
.dialog {
  border: 1px solid var(--border-strong);
  background: var(--bg-elev);
  color: var(--text);
  border-radius: var(--radius);
  padding: 0;
  max-width: min(440px, calc(100vw - 2rem));
  width: 100%;
  box-shadow: var(--shadow);
}
.dialog::backdrop {
  background: rgba(3, 6, 14, .72);
  backdrop-filter: blur(2px);
}
.dialog-inner {
  margin: 0;
  padding: 1.25rem 1.25rem 1rem;
  display: flex;
  flex-direction: column;
  gap: .75rem;
}
.dialog-header {
  display: flex;
  align-items: center;
  gap: .75rem;
}
.dialog-header h2 {
  margin: 0;
  font-size: 1.15rem;
  font-weight: 700;
}
.dialog-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px; height: 36px;
  border-radius: 50%;
  background: var(--danger-bg);
  border: 1px solid var(--danger-border);
  color: var(--danger);
  flex: 0 0 auto;
}
.dialog p {
  margin: 0;
  color: var(--text-muted);
}
.dialog-actions {
  list-style: none;
  margin: .5rem 0 0;
  padding: 0;
  display: flex;
  justify-content: flex-end;
  gap: .5rem;
  flex-wrap: wrap;
}

/* Simple open animation */
.dialog[open] {
  animation: dialog-in .15s ease-out;
}
.dialog[open]::backdrop {
  animation: backdrop-in .15s ease-out;
}
@keyframes dialog-in {
  from { opacity: 0; transform: translateY(-6px) scale(.98); }
  to   { opacity: 1; transform: none; }
}
@keyframes backdrop-in {
  from { opacity: 0; } to { opacity: 1; }
}
@media (prefers-reduced-motion: reduce) {
  .dialog[open], .dialog[open]::backdrop { animation: none; }
}

/* Forced colors */
@media (forced-colors: active) {
  .btn { border-color: ButtonBorder; color: ButtonText; background: ButtonFace; }
  .btn-danger { color: ButtonText; }
  .dialog { border-color: CanvasText; background: Canvas; color: CanvasText; }
  .dialog-icon { color: CanvasText; border-color: CanvasText; }
  .btn:focus-visible, a:focus-visible { outline: 2px solid Highlight; }
}

/* Reflow */
@media (max-width: 480px) {
  .site-header { flex-direction: column; align-items: flex-start; gap: .5rem; }
  .actions .btn { flex: 1 1 auto; justify-content: center; }
  .dialog-actions .btn { flex: 1 1 auto; justify-content: center; }
}
